import os
import torch

# =============================================================================
# PATHS & DIRECTORIES
# =============================================================================
INPUT_DIR = "./input"
METADATA_DIR = "./metadata"

# Metadata Files (Generated by the provided script)
TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

# Image Directories
# Note: Metadata file_path columns are relative to INPUT_DIR (e.g., "train_images/...")
TRAIN_IMG_DIR = os.path.join(INPUT_DIR, "train_images")
TEST_IMG_DIR = os.path.join(INPUT_DIR, "test_images")

# Working & Output Directories
WORKING_DIR = "./working"
CACHE_DIR = os.path.join(WORKING_DIR, "idea_19")
SUBMISSION_PATH = "./submission.csv"

# Ensure cache directory exists
os.makedirs(CACHE_DIR, exist_ok=True)

# =============================================================================
# DATA CONFIGURATION
# =============================================================================
# Input dimensions: 3 channels (Image, Age, Implant) x 768 x 768
IMG_SIZE = (768, 768)
NUM_CHANNELS = 3

# Batch size adjusted for A100 GPU (40GB) with Siamese architecture
# 768x768 is large, and Siamese doubles the memory footprint per sample.
BATCH_SIZE = 4
NUM_WORKERS = 4

# =============================================================================
# MODEL ARCHITECTURE
# =============================================================================
BACKBONE = "efficientnet_b2"
PRETRAINED = True
DROP_RATE = 0.3
NUM_CLASSES = 1  # Binary classification (Cancer vs No Cancer)

# =============================================================================
# TRAINING HYPERPARAMETERS
# =============================================================================
EPOCHS = 10
LEARNING_RATE = 1e-4
WEIGHT_DECAY = 1e-2

# Loss Function Configuration
# Aggressive positive weighting to approximate inverse class frequency (Imbalance ~1:47)
POS_WEIGHT = 47.0

# Gradient Strategy
# Explicitly disabled to allow large updates for the minority class
GRAD_CLIP_MAX_NORM = None

# Optimizer & Scheduler
OPTIMIZER = "AdamW"
SCHEDULER = "CosineAnnealingLR"
T_MAX = EPOCHS  # For Cosine Annealing

# =============================================================================
# REPRODUCIBILITY & HARDWARE
# =============================================================================
SEED = 42
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

# =============================================================================
# DEBUGGING / DEVELOPMENT
# =============================================================================
# Set DEBUG to True to train on a small subset of data for quick pipeline verification
DEBUG = False
MAX_SAMPLES = 1000 if DEBUG else None
